const { ZXFonts8x8 } = await import('./svision/js/platform/canvas2D/zx/zxFonts8x8.js?ver='+window.srcVersion);
// begin code

/**
 * The arcade character set of Stinger as a svision 8x8 font, in the shape of
 * ZXFonts8x8: the same 96-character set (fontsChars) and a glyph table of 16
 * hex digits per character (8 rows, one byte a row, bit 7 the left pixel), so
 * TextEntity, MenuEntity and the ZX dialogs render it like any other font.
 *
 * The table is generated by tools/rom2font.py; the sources, first match wins:
 *   - Stinger, gfx1 bank 0 of data/tiles.json (the tiles the program writes
 *     into VRAM1): digits 00h-09h, A-Z 11h-2Ah, . ( ) = - ! ' " , and the
 *     colon 7Eh of the plain second alphabet — a pixel is set when the tile
 *     pen is not 0, whatever its colour
 *   - the two-tile copyright sign of the title picture (49h+4Ah), squeezed
 *     from 9 to 8 pixels
 *   - the nearest ZX Spectrum game fonts of ~/sw/zx-fonts, ranked by pixel
 *     distance to the Stinger letters, each only for the characters it has as
 *     real text: Mimzoid Death Dude (1988) for ?, G-Force (1983) for
 *     % + / ; < > ~ and a-z, Push Off (1983) for # $ & * @ [ \ ] ^ _ £ { | }
 *
 * Monospace: 8-pixel cells as on the machine (the letters are 7 wide with an
 * empty first column); proportional trims them like the ZX font.
 */
export class StingerFonts8x8 extends ZXFonts8x8 {

  /**
   * @param {Object} app - The application instance.
   * @param {boolean} proportional - Trim the glyphs to proportional widths; false keeps the 8-pixel cells.
   */
  constructor(app, proportional) {
    super(app, proportional);
    this.id = 'StingerFonts8x8';

    this.setFontsData('');
  } // constructor

} // StingerFonts8x8
